{
  "root": {
    "name": "根主题",
    "children": [
      { "name": "分类A", "children": [ { "name": "要点1", "page": 1 } ] },
      { "name": "分类B", "children": [ { "name": "要点2", "page": 2 } ] }
    ]
  }
}
